  function esc(s){
    return String(s).replace(/[&<>"']/g, function(c){
      return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c];
    });
  }

  function hostFrom(url){
    try{
      return new URL(url).host.replace(/^www\./i, '');
    } catch(e){
      return url.replace(/^https?:\/\//i, '').split('/')[0];
    }
  }

  function render(){
    var host = document.getElementById('groups');
    host.innerHTML = '';

    DATA.forEach(function(group){
      var section = document.createElement('section');
      section.className = 'group';

      var head = document.createElement('div');
      head.className = 'group-head';
      head.innerHTML =
        '<div class="group-title">' +
          '<span class="group-name">' + esc(group.n) + '</span>' +
          '<span class="group-pill">' + group.l.length + '</span>' +
        '</div>' +
        '<span class="chev">▾</span>';

      var body = document.createElement('div');
      body.className = 'group-body';

      group.l.forEach(function(url){
        var item = document.createElement('a');
        item.className = 'link-item';
        item.href = url;
        item.target = '_blank';
        item.rel = 'noopener noreferrer';

        var main = document.createElement('div');
        main.className = 'link-main';

        var urlEl = document.createElement('div');
        urlEl.className = 'link-url';
        urlEl.textContent = url.replace(/^https?:\/\//i, '');

        var hostEl = document.createElement('div');
        hostEl.className = 'link-host';
        hostEl.textContent = hostFrom(url);

        main.appendChild(urlEl);
        main.appendChild(hostEl);

        var actions = document.createElement('div');
        actions.className = 'actions';

        var copyBtn = document.createElement('button');
        copyBtn.type = 'button';
        copyBtn.className = 'btn';
        copyBtn.textContent = 'Copy';
        copyBtn.addEventListener('click', function(e){
          e.preventDefault();
          e.stopPropagation();
          if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(url).then(function(){
              copyBtn.classList.add('ok');
              copyBtn.textContent = 'OK';
              showToast('Copied');
              setTimeout(function(){
                copyBtn.classList.remove('ok');
                copyBtn.textContent = 'Copy';
              }, 900);
            }).catch(function(){
              fallbackCopy(url, copyBtn);
            });
          } else {
            fallbackCopy(url, copyBtn);
          }
        });

        var openBtn = document.createElement('button');
        openBtn.type = 'button';
        openBtn.className = 'btn';
        openBtn.textContent = 'Open';
        openBtn.addEventListener('click', function(e){
          e.preventDefault();
          e.stopPropagation();
          window.open(url, '_blank', 'noopener');
        });

        actions.appendChild(copyBtn);
        actions.appendChild(openBtn);

        item.appendChild(main);
        item.appendChild(actions);
        body.appendChild(item);
      });

      head.addEventListener('click', function(){
        section.classList.toggle('closed');
      });

      section.appendChild(head);
      section.appendChild(body);
      host.appendChild(section);
    });

    updateCounter();
  }

  function fallbackCopy(text, btn){
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try {
      document.execCommand('copy');
      btn.classList.add('ok');
      btn.textContent = 'OK';
      showToast('Copied');
    } catch (e) {
      showToast('Copy failed');
    }
    setTimeout(function(){
      btn.classList.remove('ok');
      btn.textContent = 'Copy';
    }, 900);
    document.body.removeChild(ta);
  }

  function showToast(msg){
    var toast = document.getElementById('toast');
    toast.textContent = msg || 'Copied';
    toast.classList.add('show');
    clearTimeout(showToast.t);
    showToast.t = setTimeout(function(){
      toast.classList.remove('show');
    }, 1400);
  }

  function updateCounter(){
    var groups = document.querySelectorAll('.group');
    var totalLinks = 0;
    groups.forEach(function(g){
      totalLinks += g.querySelectorAll('.link-item').length;
    });
    document.getElementById('count').textContent = groups.length + ' groups • ' + totalLinks + ' links';
  }

  function filter(){
    var q = document.getElementById('search').value.trim().toLowerCase();
    var groups = document.querySelectorAll('.group');
    var any = false;

    groups.forEach(function(group){
      var name = group.querySelector('.group-name').textContent.toLowerCase();
      var urls = Array.from(group.querySelectorAll('.link-url')).map(function(el){ return el.textContent.toLowerCase(); }).join(' ');
      var hosts = Array.from(group.querySelectorAll('.link-host')).map(function(el){ return el.textContent.toLowerCase(); }).join(' ');
      var hay = name + ' ' + urls + ' ' + hosts;

      var show = !q || hay.indexOf(q) !== -1;
      group.classList.toggle('hidden', !show);

      if (show) any = true;
    });

    document.getElementById('empty').classList.toggle('show', !any);
    updateCounter();
  }

  document.getElementById('search').addEventListener('input', filter);

  document.addEventListener('keydown', function(e){
    if (e.key === '/' && document.activeElement !== document.getElementById('search')) {
      e.preventDefault();
      var s = document.getElementById('search');
      s.focus();
      s.select();
    }
  });

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', render);
  } else {
    render();
  }
})();
